  insert into public.experiences (id, company, role, location, start_date, end_date, is_current, summary, highlights, tech, sort_order) values
    ('6afc9d01-a3b7-0705-57d1-1dded97581bc', 'Newgen Software Technologies', 'Software Engineer', null, '2025-07-01', null, true, null, array['Developed and maintained enterprise applications using Java, Spring Boot, JavaScript and SQL, ensuring scalable and high-performance solutions for business clients.', 'Designed and implemented workflows and business rules using Newgen iBPS, Process Designer and BRMS to streamline operational processes and improve efficiency.', 'Built and integrated RESTful APIs, backend utilities and responsive UI components to support seamless system integration and an enhanced user experience.', 'Performed debugging, manual testing and API validation using Postman while ensuring application quality, performance and timely delivery of project requirements.']::text[], array['Java', 'Spring Boot', 'JavaScript', 'SQL', 'Newgen iBPS', 'Process Designer', 'BRMS', 'Postman']::text[], 1),
    ('b7d3008a-ce03-5e7b-5d75-2542adbf89ca', 'Newgen Software Technologies', 'Software Engineer Intern', null, '2025-01-01', '2025-06-30', false, null, array['Assisted in developing and maintaining enterprise applications using Java, SQL and JavaScript, supporting workflow automation and backend processes.', 'Worked on implementing business workflows and validating APIs using Postman to ensure smooth system integration and functionality.', 'Supported debugging, testing and issue resolution activities to improve application performance and user experience.', 'Collaborated with development and business teams while gaining hands-on experience in enterprise software solutions and SDLC practices.']::text[], array['Java', 'SQL', 'JavaScript', 'Postman']::text[], 2);
  insert into public.projects (id, title, description, period, tech, image_path, live_url, repo_url, is_featured, sort_order) values
    ('e93fc50f-6d10-e8a6-f339-84565ffb07d5', 'E-commerce Platform', 'A full-featured e-commerce web application where users can browse and purchase products, search by category and price, and manage profiles through login and signup pages. Includes banners for special offers, add-to-cart and remove-from-cart functionality, and secure payment processing integrated with the Stripe API.', 'Apr 2024 – May 2025', array['React.js', 'Tailwind CSS', 'Node.js', 'Express.js', 'MongoDB', 'Stripe API', 'JavaScript', 'HTML', 'CSS']::text[], null, null, null, true, 1),
    ('119f7b4f-7570-effd-e335-86224986b2ae', 'Multi-Calculator Website', 'A dynamic calculator website featuring multiple types of calculators categorised under Business, Mathematics, Fitness & Health, and Others. Built to showcase web development and problem-solving skills with a user-friendly interface that meets diverse functional needs.', 'Apr 2023 – May 2024', array['HTML', 'CSS', 'Bootstrap', 'JavaScript']::text[], null, null, null, false, 2);
